message.content:
{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a pale, lightly textured ground with small tufts of grass under its paws. It has the overall build, dense shaggy fur, and proportions of a brown bear, with a thick body, short neck, and sturdy limbs, but its body is interspersed with large, glossy, dark reddish-brown chitinous plates and it bears a single long, curved, glossy black horn on its forehead. The fur is predominantly medium to dark brown with lighter tan on the muzzle and underside, and the plates have a hard, reflective, segmented appearance. No tail or wings are visible.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with a broad, elongated muzzle, black nose with visible nostrils, small dark brown eyes, light tan fur on the muzzle and around the mouth, and a slightly open mouth showing the lower lip",
      "where": "at the front end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large, glossy black, smooth, strongly curved horn tapering to a sharp point, curving upward and forward, with two small tooth-like notches on the inner concave edge near the tip, with a slightly flared base set into the fur",
      "where": "centered on the forehead on top of the head between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred ears with dark brown fur, slightly lighter inside",
      "where": "on top of the head, one on each side behind the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, columnar legs covered in long shaggy dark brown fur, with slightly lighter fur on the inner and lower chest/belly area",
      "where": "under the torso, two forelegs supporting the front and two hindlegs supporting the rear in a standing quadrupedal stance"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dark brown fur on top and five visible pale, curved claws on each paw extending forward from the toes",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "plates",
      "looks_like": "multiple large, dome-shaped, highly glossy dark mahogany-brown plates with segmented lines and cracked patterning and bright specular highlights, appearing hard and chitinous",
      "where": "distributed across the body: two small plates on the upper back, one large plate on the mid-side, one on the hip/rear, two collar-like plates around the lower neck/shoulder, one on each shoulder joint and one on each outer hind leg joint, with smaller plates partially visible on the inner foreleg and hindleg"
    },
    {
      "part": "markings",
      "looks_like": "a horizontal row of six small, vertically oval, black openings with thin pale rims, resembling spiracles, set in a line",
      "where": "on the lower side of the torso just below the large lateral plate, above the pale belly fur"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 0
}
